// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address logger) public {
        vm.deal(logger, 1 ether);

        vm.prank(address(0));
        c.setApprovedLogger(logger, true);

        bool ok;
        vm.prank(logger);
        try c.logCreated(address(0)) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
